import {
  type GraphEdge,
  type GraphNode,
  KnowledgeGraph,
  type NodeId,
} from "../graph.ts";
import { readTools, writeTools } from "../graph-tools.ts";
import type { Msg as GraphMsg, Sidebar } from "../graph-view.ts";
import { interactionAt } from "../interactions.ts";
import { layout, type Position } from "../layout.ts";
import { GRAPH_UPDATE_SYSTEM, graphUpdatePrompt } from "../prompt.ts";
import { selectedSample, selectSample } from "../samples/index.ts";
import { overlaps, type ThreadId } from "../selection.ts";
import { type MessageIdx, runThread, Thread } from "../thread.ts";
import { ThreadTree } from "../threads.ts";
import { AppView, type Msg, type State } from "../view.ts";

/** The editable fields of a node or edge: the id addresses it, so it is not
 * part of what the sidebar edits. */
function draftOf(node: GraphNode): Omit<GraphNode, "id">;
function draftOf(edge: GraphEdge): Omit<GraphEdge, "id">;
function draftOf<T extends { id: string }>(item: T): Omit<T, "id"> {
  const { id: _id, ...rest } = item;
  return rest;
}

function connect(): WebSocket {
  const proto = window.location.protocol === "https:" ? "wss:" : "ws:";
  return new WebSocket(`${proto}//${window.location.host}/api/socket`);
}

/** Prototype 1: the task transcript, with learning threads hanging off the
 * passages the user picks out of it. */
export function mount(container: HTMLElement): void {
  // One socket for the whole app: every Thread adds its own
  // listener and drops frames whose requestId it does not own, so streams
  // interleave over the single connection.
  const socket = connect();
  // Scoped to the user, not to a thread: it outlives every thread in the tree
  // and is discarded only by a page load.
  const graph = new KnowledgeGraph();
  const tree = new ThreadTree(
    socket,
    new Thread(socket, { initialTurns: selectedSample()?.turns }),
    () => {
      refresh();
      view.sync(state);
    },
  );
  // The thread on the left. Moved only by the arrows.
  let focus = tree.root;
  let sidebar: Sidebar = { type: "closed" };
  // Graph updates run one at a time: two in flight would each be handed the
  // pre-update graph and mint rival nodes for the same concept. Appending to
  // this chain is the whole serialization.
  let updates: Promise<void> = Promise.resolve();
  // The layout is a few hundred iterations, and refresh() runs on every
  // keystroke, so it is recomputed only when the shape of the graph changes.
  let placement = new Map<NodeId, Position>();
  let placedFor = "";
  // Purely presentational, and per thread: which messages the user has
  // expanded past the collapsed height.
  const expanded = new Map<ThreadId, Set<number>>();
  function expandedFor(id: ThreadId): Set<number> {
    let set = expanded.get(id);
    if (!set) {
      set = new Set();
      expanded.set(id, set);
    }
    return set;
  }

  const state: State = {
    sample: selectedSample()?.id ?? "",
    messages: [],
    inFlight: false,
    draft: "",
    split: false,
    depth: 0,
    canDescend: false,
    thread: focus,
    marks: [],
    activeMark: null,
    anchor: null,
    tab: "threads",
    graph: { nodes: [], edges: [], sidebar },
    build: { type: "idle" },
    query: "",
    expanded: new Set(),
    child: null,
  };

  /** Re-projects the tree onto the view's state. Everything but the fields the
   * user is editing is derived, so this runs after every dispatch. */
  /** The graph projected onto view state: positions from `layout`, and the
   * sidebar the user is editing. */
  function refreshGraph(): void {
    const nodes = graph.nodes;
    const edges = graph.edges;
    const shape = [
      ...nodes.map((n) => n.id),
      ...edges.map((e) => `${e.id}:${e.from}->${e.to}`),
    ].join(",");
    if (shape !== placedFor) {
      placement = layout(graph);
      placedFor = shape;
    }
    const at = (id: NodeId): Position =>
      placement.get(id) ?? { x: 0.5, y: 0.5 };
    state.graph = {
      nodes: nodes.map((n) => ({ ...n, pos: at(n.id) })),
      edges: edges.map((e) => ({ ...e, from_: at(e.from), to_: at(e.to) })),
      sidebar,
    };
  }

  function refresh(): void {
    refreshGraph();
    const node = tree.get(focus);
    state.thread = focus;
    state.depth = state.split ? tree.path(focus).length : 0;
    state.canDescend = node.activeChild !== null;
    state.messages = node.thread.messages;
    state.inFlight = node.thread.inFlight;
    state.draft = node.draft;
    state.marks = tree.marks(focus);
    state.expanded = expandedFor(focus);
    state.activeMark = node.activeChild;
    const activeChild = node.activeChild;
    if (!activeChild) {
      state.child = null;
      return;
    }
    const child = tree.get(activeChild);
    state.child = {
      messages: child.thread.messages,
      inFlight: child.thread.inFlight,
      draft: child.draft,
      expanded: expandedFor(activeChild),
    };
  }

  function sync(): void {
    refresh();
    view.sync(state);
  }

  /** One detached thread per user interaction, writing straight into the graph
   * through its tools. Queued against every other update rather than run
   * concurrently, and never awaited by the user: the learning thread answers
   * them regardless, and a failure here is invisible outside the console. */
  function queueGraphUpdate(
    thread: ThreadId,
    index: MessageIdx,
  ): Promise<boolean> {
    const interaction = interactionAt(tree, thread, index);
    const done = updates
      .then(async () => {
        // Read inside the queued step, so this update sees the previous one's
        // writes rather than the graph as it stood when it was enqueued.
        const result = await runThread(socket, {
          system: GRAPH_UPDATE_SYSTEM,
          prompt: graphUpdatePrompt(interaction, graph.render()),
          tools: writeTools(graph),
          yieldSchema: "text",
        });
        if (result.status === "error") {
          console.error(result.error);
          return false;
        }
        return true;
      })
      .catch((e: unknown) => {
        console.error(e);
        return false;
      })
      .then((ok) => {
        sync();
        return ok;
      });
    updates = done.then(() => undefined);
    return done;
  }

  /** The sample's own turns: a loaded transcript is a session that happened
   * before this page existed, so no live update ever ran over it. Every turn
   * after these came from an interaction that updated the graph itself, so
   * enumerating once at mount is what keeps the build from double-counting. */
  const sampleInteractions: MessageIdx[] = tree
    .get(tree.root)
    .thread.messages.flatMap((m, i) =>
      m.role === "user" && m.type === "text" ? [i as MessageIdx] : [],
    );

  /** Walks the loaded sample's turns through the same queue the live updates
   * use, so an interaction mid-build interleaves rather than races. */
  function runBuild(): void {
    if (state.build.type !== "idle") return;
    const total = sampleInteractions.length;
    if (total === 0) return;
    state.build = { type: "running", done: 0, total, failed: 0 };
    void (async () => {
      for (const index of sampleInteractions) {
        const ok = await queueGraphUpdate(tree.root, index);
        const build = state.build;
        if (build.type !== "running") return;
        state.build = {
          type: "running",
          done: build.done + 1,
          total: build.total,
          failed: build.failed + (ok ? 0 : 1),
        };
        sync();
      }
      const build = state.build;
      state.build = {
        type: "done",
        failed: build.type === "running" ? build.failed : 0,
      };
      sync();
    })();
  }

  function send(id: ThreadId): void {
    const node = tree.get(id);
    const text = node.draft.trim();
    if (text === "" || node.thread.inFlight) return;
    node.draft = "";
    // Nothing is streaming while the thread is idle, so the turn lands at the
    // end of `messages` - which is its citable address.
    const index = node.thread.messages.length as MessageIdx;
    node.thread.send(text).then(undefined, (e: unknown) => {
      console.error(e);
    });
    void queueGraphUpdate(id, index);
  }

  /** The graph tab's own reducer. It writes to the graph and to `sidebar`;
   * everything the canvas shows is re-derived in refreshGraph(). */
  function updateGraph(msg: GraphMsg): void {
    switch (msg.type) {
      case "SELECT_NODE": {
        const node = graph.node(msg.id);
        if (!node) break;
        sidebar = {
          type: "node",
          id: node.id,
          draft: draftOf(node),
          error: null,
        };
        break;
      }
      case "SELECT_EDGE": {
        const edge = graph.edge(msg.id);
        if (!edge) break;
        sidebar = {
          type: "edge",
          id: edge.id,
          draft: draftOf(edge),
          error: null,
        };
        break;
      }
      case "CLOSE":
        sidebar = { type: "closed" };
        break;
      case "NODE_FIELD":
        if (sidebar.type === "node") sidebar.draft[msg.field] = msg.value;
        break;
      case "LEVEL_CHANGED":
        if (sidebar.type === "node") sidebar.draft.level = msg.level;
        break;
      case "EDGE_FIELD":
        if (sidebar.type === "edge") sidebar.draft[msg.field] = msg.value;
        break;
      case "SAVE": {
        if (sidebar.type === "closed") break;
        const result =
          sidebar.type === "node"
            ? graph.putNode({ id: sidebar.id, ...sidebar.draft })
            : graph.putEdge({ id: sidebar.id, ...sidebar.draft });
        // A rejected save keeps the draft, so the user's typing survives.
        sidebar.error = result.status === "error" ? result.error : null;
        break;
      }
      case "DELETE": {
        if (sidebar.type === "closed") break;
        if (sidebar.type === "node") graph.deleteNode(sidebar.id);
        else graph.deleteEdge(sidebar.id);
        sidebar = { type: "closed" };
        break;
      }
    }
  }

  function update(state: State, msg: Msg): void {
    const node = tree.get(focus);
    switch (msg.type) {
      case "DRAFT_CHANGED":
        node.draft = msg.draft;
        break;
      case "SAMPLE_CHANGED":
        selectSample(msg.id === "" ? undefined : msg.id);
        break;
      case "TAB_CHANGED":
        state.tab = msg.tab;
        break;
      case "GRAPH_MSG":
        updateGraph(msg.msg);
        break;
      case "SUBMIT":
        send(focus);
        break;
      case "BUILD":
        runBuild();
        break;
      case "GO_DEEPER": {
        if (!state.split) {
          state.split = true;
          break;
        }
        const child = node.activeChild;
        if (!child) break;
        focus = child;
        state.anchor = null;
        state.query = "";
        break;
      }
      case "GO_BACK": {
        const parent = node.origin?.anchor.thread;
        if (parent === undefined) state.split = false;
        else focus = parent;
        state.anchor = null;
        state.query = "";
        break;
      }
      case "TOGGLE_EXPANDED": {
        const set = expandedFor(focus);
        if (!set.delete(msg.index)) set.add(msg.index);
        break;
      }
      case "SELECTION_CHANGED":
        state.anchor = msg.anchor;
        node.activeChild = null;
        break;
      case "MARK_CLICKED":
        state.anchor = null;
        node.activeChild = msg.thread;
        break;
      case "LEARNING_MSG":
        switch (msg.msg.type) {
          case "ACTION": {
            const anchor = state.anchor;
            if (!anchor || overlaps(state.marks, anchor)) break;
            const id = tree.open(anchor, msg.msg.action, {
              tools: readTools(graph),
              graph: graph.render(),
            });
            state.anchor = null;
            state.query = "";
            void queueGraphUpdate(id, 0 as MessageIdx);
            tree
              .get(id)
              .thread.start()
              .then(undefined, (e: unknown) => {
                console.error(e);
              });
            break;
          }
          case "QUERY_CHANGED":
            state.query = msg.msg.query;
            break;
        }
        break;
      case "CHILD_MSG": {
        const activeChild = node.activeChild;
        if (!activeChild) break;
        switch (msg.msg.type) {
          case "DRAFT_CHANGED":
            tree.get(activeChild).draft = msg.msg.draft;
            break;
          case "SUBMIT":
            send(activeChild);
            break;
          case "TOGGLE_EXPANDED": {
            const set = expandedFor(activeChild);
            if (!set.delete(msg.msg.index)) set.add(msg.msg.index);
            break;
          }
        }
        break;
      }
    }
    refresh();
  }

  let dispatching = false;
  function dispatch(msg: Msg): void {
    if (dispatching) throw new Error("dispatch-in-dispatch");
    dispatching = true;
    update(state, msg);
    view.sync(state);
    dispatching = false;
  }

  // e2e specs seed a known graph through this handle rather than driving the
  // extraction thread first, so the sidebar cases stay deterministic.
  (window as unknown as { __graph?: KnowledgeGraph }).__graph = graph;

  refresh();
  const view = new AppView(container, dispatch, state);
}

import type Anthropic from "@anthropic-ai/sdk";
import {
  type EdgeId,
  type GraphId,
  type GraphResult,
  isEdgeId,
  isNodeId,
  type KnowledgeGraph,
  LEVELS,
  type Level,
  type NodeId,
} from "./graph.ts";
import {
  type Tool,
  type ToolName,
  type ToolResult,
  toolset,
} from "./thread.ts";

/** Batches are not transactional: an entry that fails is reported on its own
 * line and its neighbours still apply, so the model can fix one entry rather
 * than reconstruct the whole call. Only unusable *input* fails the call. */
const ok = (lines: ReadonlyArray<string>): ToolResult => ({
  status: "ok",
  text: lines.join("\n"),
});
const err = (error: string): ToolResult => ({ status: "error", error });

const ID_LIST: Anthropic.Tool.InputSchema = {
  type: "object",
  properties: {
    ids: {
      type: "array",
      items: { type: "string" },
      description: "Node ids (n0, n1, ...) and/or edge ids (e0, e1, ...).",
    },
  },
  required: ["ids"],
};

const NODE_PROPERTIES = {
  id: {
    type: "string",
    description:
      "Omit to create a new node; give it to update an existing one.",
  },
  title: {
    type: "string",
    description: "Up to 5 words, unique among nodes.",
  },
  description: { type: "string", description: "What this knowledge is." },
  notes: {
    type: "string",
    description:
      "Your read on this user's grasp of it, including any misconceptions.",
  },
  level: {
    type: "integer",
    enum: [1, 2, 3, 4],
    description: LEVELS.map((label, i) => `${i + 1} ${label}`).join(", "),
  },
} as const;

const EDGE_PROPERTIES = {
  id: {
    type: "string",
    description:
      "Omit to create a new edge; give it to update an existing one.",
  },
  from: { type: "string", description: "Source node id." },
  to: { type: "string", description: "Target node id." },
  title: { type: "string", description: "1-2 words." },
  description: {
    type: "string",
    description: "What the relationship actually is.",
  },
} as const;

function list(input: Record<string, unknown>, key: string): unknown[] | string {
  const value = input[key];
  if (!Array.isArray(value)) return `"${key}" must be an array`;
  return value;
}

function entry(
  value: unknown,
  index: number,
): Record<string, unknown> | string {
  return typeof value === "object" && value !== null && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : `entry ${index}: not an object`;
}

const text = (value: unknown): string =>
  typeof value === "string" ? value : "";

function optionalId(value: unknown): string | undefined | null {
  if (value === undefined || value === null || value === "") return undefined;
  return typeof value === "string" ? value : null;
}

function level(value: unknown): Level | undefined {
  return value === 1 || value === 2 || value === 3 || value === 4
    ? value
    : undefined;
}

const line = (index: number, result: GraphResult): string =>
  result.status === "ok"
    ? `entry ${index}: ${result.message}`
    : `entry ${index}: error: ${result.error}`;

function getTool(graph: KnowledgeGraph): Tool {
  return {
    spec: {
      name: "get",
      description:
        "Read the full record for each id: a node with its description, notes, level and every incident edge, or an edge with its endpoints. Unknown ids are reported per id.",
      input_schema: ID_LIST,
    },
    execute: async (input) => {
      const ids = list(input, "ids");
      if (typeof ids === "string") return err(ids);
      if (ids.some((id) => typeof id !== "string"))
        return err("every id must be a string");
      if (ids.length === 0) return err('"ids" is empty');
      return { status: "ok", text: graph.get(ids as GraphId[]) };
    },
  };
}

function putNodesTool(graph: KnowledgeGraph): Tool {
  return {
    spec: {
      name: "put_nodes",
      description:
        "Create or update nodes in one call. An entry with no id creates a node and the result reports its new id; an entry with an id updates that node.",
      input_schema: {
        type: "object",
        properties: {
          nodes: {
            type: "array",
            items: {
              type: "object",
              properties: NODE_PROPERTIES,
              required: ["title", "description", "notes", "level"],
            },
          },
        },
        required: ["nodes"],
      },
    },
    execute: async (input) => {
      const nodes = list(input, "nodes");
      if (typeof nodes === "string") return err(nodes);
      if (nodes.length === 0) return err('"nodes" is empty');
      return ok(
        nodes.map((value, index) => {
          const node = entry(value, index);
          if (typeof node === "string") return node;
          const id = optionalId(node.id);
          if (id === null)
            return `entry ${index}: error: "id" must be a string`;
          if (id !== undefined && !isNodeId(id))
            return `entry ${index}: error: ${id} is not a node id`;
          const lvl = level(node.level);
          if (lvl === undefined)
            return `entry ${index}: error: "level" must be 1, 2, 3 or 4`;
          return line(
            index,
            graph.putNode({
              ...(id === undefined ? {} : { id: id as NodeId }),
              title: text(node.title),
              description: text(node.description),
              notes: text(node.notes),
              level: lvl,
            }),
          );
        }),
      );
    },
  };
}

function putEdgesTool(graph: KnowledgeGraph): Tool {
  return {
    spec: {
      name: "put_edges",
      description:
        "Create or update edges in one call. Nodes created by an earlier put_nodes call can be referenced here. Several edges may join the same pair of nodes.",
      input_schema: {
        type: "object",
        properties: {
          edges: {
            type: "array",
            items: {
              type: "object",
              properties: EDGE_PROPERTIES,
              required: ["from", "to", "title", "description"],
            },
          },
        },
        required: ["edges"],
      },
    },
    execute: async (input) => {
      const edges = list(input, "edges");
      if (typeof edges === "string") return err(edges);
      if (edges.length === 0) return err('"edges" is empty');
      return ok(
        edges.map((value, index) => {
          const edge = entry(value, index);
          if (typeof edge === "string") return edge;
          const id = optionalId(edge.id);
          if (id === null)
            return `entry ${index}: error: "id" must be a string`;
          if (id !== undefined && !isEdgeId(id))
            return `entry ${index}: error: ${id} is not an edge id`;
          if (typeof edge.from !== "string" || typeof edge.to !== "string")
            return `entry ${index}: error: "from" and "to" must be node ids`;
          return line(
            index,
            graph.putEdge({
              ...(id === undefined ? {} : { id: id as EdgeId }),
              from: edge.from as NodeId,
              to: edge.to as NodeId,
              title: text(edge.title),
              description: text(edge.description),
            }),
          );
        }),
      );
    },
  };
}

function deleteTool(graph: KnowledgeGraph): Tool {
  return {
    spec: {
      name: "delete",
      description:
        "Delete nodes and edges by id. Deleting a node also deletes every edge incident to it.",
      input_schema: ID_LIST,
    },
    execute: async (input) => {
      const ids = list(input, "ids");
      if (typeof ids === "string") return err(ids);
      if (ids.length === 0) return err('"ids" is empty');
      return ok(
        ids.map((id, index) => {
          if (typeof id !== "string")
            return `entry ${index}: error: id must be a string`;
          if (isNodeId(id)) return line(index, graph.deleteNode(id as NodeId));
          if (isEdgeId(id)) return line(index, graph.deleteEdge(id as EdgeId));
          return `entry ${index}: error: ${id} is not a node or edge id`;
        }),
      );
    },
  };
}

/** `get` only: what a learning thread gets. It reads the student model, it
 * never writes to it. */
export function readTools(graph: KnowledgeGraph): Record<ToolName, Tool> {
  return toolset(getTool(graph));
}

/** `get`, `put_nodes`, `put_edges`, `delete`: what the extraction thread gets. */
export function writeTools(graph: KnowledgeGraph): Record<ToolName, Tool> {
  return toolset(
    getTool(graph),
    putNodesTool(graph),
    putEdgesTool(graph),
    deleteTool(graph),
  );
}

stdout:
/** One id space over nodes and edges, so `get` takes a single list. */
export type GraphId = NodeId | EdgeId;
/** Minted by the graph (`n0`, `n1`, ...). Opaque; never derived from the title. */
export type NodeId = string & { readonly __brand: "NodeId" };
/** Minted by the graph (`e0`, `e1`, ...). */
export type EdgeId = string & { readonly __brand: "EdgeId" };
/** The agent's estimate, not a measurement. A misconception can look fluent,
 * so it belongs in `notes`, not here. */
export type Level = 1 | 2 | 3 | 4;
export const LEVELS = ["unfamiliar", "emerging", "working", "fluent"] as const;
export const levelLabel = (level: Level) => `${level} ${LEVELS[level - 1]}`;
export type GraphNode = {
  id: NodeId;
  /** Unique among nodes and non-empty, up to ~5 words. A label, not the key. */
  title: string;
  /** What the domain knowledge itself is. */
  description: string;
  /** The agent's read on this user's grasp of it, including misconceptions. */
  notes: string;
  level: Level;
};
export type GraphEdge = {
  id: EdgeId;
  from: NodeId;
  to: NodeId;
  /** 1-2 words. Several edges may join the same pair. */
  title: string;
  description: string;
};
export type GraphResult =
  | { status: "ok"; message: string }
  | { status: "error"; error: string };
export const isNodeId = (id: string): id is NodeId => id.startsWith("n");
export const isEdgeId = (id: string): id is EdgeId => id.startsWith("e");
export class KnowledgeGraph {
  #nodes = new Map<NodeId, GraphNode>();
  #edges = new Map<EdgeId, GraphEdge>();
  #next = 0;
  get nodes(): ReadonlyArray<GraphNode> {
    return [...this.#nodes.values()];
  }
  get edges(): ReadonlyArray<GraphEdge> {
    return [...this.#edges.values()];
  }
  node(id: NodeId): GraphNode | undefined {
    return this.#nodes.get(id);
  }
  edge(id: EdgeId): GraphEdge | undefined {
    return this.#edges.get(id);
  }
  /** Creates with a fresh id when `id` is omitted, updates in place when it is
   * given. Rejects an unknown id, an empty title, or a title already used by
   * another node. */
  putNode(node: Omit<GraphNode, "id"> & { id?: NodeId }): GraphResult {
    const title = node.title.trim();
    if (title === "") return { status: "error", error: "node title is empty" };
    if (node.id !== undefined && !this.#nodes.has(node.id))
      return { status: "error", error: `no node with id ${node.id}` };
    for (const other of this.#nodes.values())
      if (other.title === title && other.id !== node.id)
        return {
          status: "error",
          error: `title "${title}" is already used by node ${other.id}`,
        };
    const id = node.id ?? (`n${this.#next++}` as NodeId);
    this.#nodes.set(id, {
      id,
      title,
      description: node.description,
      notes: node.notes,
      level: node.level,
    });
    return {
      status: "ok",
      message: `${node.id === undefined ? "created" : "updated"} node ${id} "${title}"`,
    };
  }
  /** Cascades to incident edges. */
  deleteNode(id: NodeId): GraphResult {
    const node = this.#nodes.get(id);
    if (!node) return { status: "error", error: `no node with id ${id}` };
    let removed = 0;
